from datetime import date, datetime


def reconcile(bank, ledger, window=2):
    def parse_date(value):
        try:
            return date.fromisoformat(value)
        except ValueError:
            return datetime.fromisoformat(value).date()

    bank_dates = [parse_date(item[1]) for item in bank]
    ledger_dates = [parse_date(item[1]) for item in ledger]

    bank_order = sorted(
        range(len(bank)),
        key=lambda i: (bank_dates[i], bank[i][0])
    )

    unmatched_ledger_indices = set(range(len(ledger)))
    matches = []
    matched_bank_indices = set()

    for bank_index in bank_order:
        bank_id, _, bank_amount = bank[bank_index]
        candidates = []

        for ledger_index in unmatched_ledger_indices:
            _, _, ledger_amount = ledger[ledger_index]
            if (
                bank_amount == ledger_amount
                and abs((bank_dates[bank_index] - ledger_dates[ledger_index]).days)
                <= window
            ):
                candidates.append(ledger_index)

        if candidates:
            ledger_index = min(
                candidates,
                key=lambda i: (ledger_dates[i], ledger[i][0])
            )
            matches.append((bank_id, ledger[ledger_index][0]))
            matched_bank_indices.add(bank_index)
            unmatched_ledger_indices.remove(ledger_index)

    unmatched_bank = [
        bank[i][0] for i in range(len(bank))
        if i not in matched_bank_indices
    ]
    unmatched_ledger = [
        ledger[i][0] for i in range(len(ledger))
        if i in unmatched_ledger_indices
    ]

    return matches, unmatched_bank, unmatched_ledger
